def header(lang, c, sub=False):
    prefix = '/' + lang + '/'
    links = ''.join(f'<a href="{prefix}#{i}">{escape(t)}</a>' for i,t in zip(['work','experience','expertise','contact'],c['nav']))
    return f'''<a class="skip" href="#main">{'Skip to content' if lang=='en' else 'Zum Inhalt'}</a>
    <header class="header"><a class="brand" href="/{lang}/" aria-label="Sagar Kriplani — Home"><span class="monogram">sk<span>.</span></span><span>SAGAR KRIPLANI<small>M.Sc. Scientific Instrumentation</small></span></a><nav aria-label="{'Main navigation' if lang=='en' else 'Hauptnavigation'}">{links}</nav><div class="utilities"><a class="language" href="/{'de' if lang=='en' else 'en'}/{'cv/' if sub=='cv' else 'legal/' if sub=='legal' else ''}" lang="{'de' if lang=='en' else 'en'}">{'DE' if lang=='en' else 'EN'} <span aria-hidden="true">↗</span></a><button class="theme" type="button" aria-label="{'Toggle dark theme' if lang=='en' else 'Dunkles Design umschalten'}" aria-pressed="false">◐</button><button class="menu-toggle" type="button" aria-expanded="false" aria-label="{'Toggle menu' if lang=='en' else 'Menü umschalten'}" aria-controls="mobile-nav">☰</button></div><nav id="mobile-nav" class="mobile-nav" hidden>{links}</nav></header>'''

def head(lang,c,title=None,path=None):
    path = path or f'/{lang}/'
    return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title>{escape(title or ('Sagar Kriplani | '+c['title']))}</title><meta name="description" content="{escape(c['intro'],quote=True)}"><link rel="canonical" href="https://sagar-kriplani.github.io{path}"><link rel="alternate" hreflang="en" href="https://sagar-kriplani.github.io/en/"><link rel="alternate" hreflang="de" href="https://sagar-kriplani.github.io/de/"><link rel="alternate" hreflang="x-default" href="https://sagar-kriplani.github.io/"><meta property="og:title" content="Sagar Kriplani | {escape(c['title'])}"><meta property="og:description" content="{escape(c['intro'],quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="https://sagar-kriplani.github.io{path}"><meta property="og:image" content="https://sagar-kriplani.github.io/assets/images/sagar-kriplani.webp"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script></head><body>{header(lang,c)}'''

def footer(lang,c):
    return f'''<footer class="footer"><a class="footer-name" href="/{lang}/">Sagar Kriplani<span> {c['footer']}</span></a><span>© 2026</span><a href="/{lang}/legal/">{c['legal']} ↗</a><a href="/{lang}/#top" aria-label="{'Back to top' if lang=='en' else 'Nach oben'}">↑</a></footer></body></html>'''

